{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, complete fastening at marked workbench location, and place reusable equipment on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench where the fastening must occur.",
        "required_count": 1
      , "binding_policy": "SHARED"
      , "candidate_categories": ["marked spot on table", "black platform"]
      , "required_properties": ["receives fastening"]
      }
    , {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A physical part compatible with the target location that performs the fastening.",
        "required_count": 1
      , "binding_policy": "DISTINCT"
      , "candidate_categories": ["screw", "bolt", "clip", "block"]
      , "required_properties": ["compatible with target", "manipulatable"]
      }
    , {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to apply force or secure the component.",
        "required_count": 1
      , "binding_policy": "REUSABLE"
      , "candidate_categories": ["screwdriver", "wrench", "gripper"]
      , "required_properties": ["capable of applying force"]
      }
    , {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The surface of the workbench where the tool is returned.",
        "required_count": 1
      , "binding_policy": "SHARED"
      , "candidate_categories": ["wooden table top"]
      , "required_properties": ["flat", "horizontal"]
      }
    ],
    "functional_relations": [
      {
        "id": "component_suits_target",
        "relation": "A fastening component must be compatible with the target location.",
        "participant_roles": ["fastening_component", "fastening_target"]
      , "required": true
      }
    , {
        "id": "tool_secures_component",
        "relation": "A fastening tool is used to secure a component to the target.",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_target"]
      , "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "perform_fastening",
        "operation": "Secure the component to the target using the tool.",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_target"]
      , "operation_count": 1
      }
    , {
        "id": "return_tool",
        "operation": "Place the tool on the workbench surface.",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      , "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        { "label": "black rectangular object", "visual_description": "Black flat object on table surface" }
      ],
      "fastening_component": [
        { "label": "yellow blocks", "visual_description": "Small yellow objects on top of black object" }
      ],
      "fastening_tool": [
        { "label": "robot gripper", "visual_description": "Yellow/grey mechanical hand visible in image 3" }
      ],
      "workbench_surface": [
        { "label": "wooden table top", "visual_description": "Brown wooden surface of the desk" }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "Blue Cabinet",
        "visual_description": "Tall blue storage unit with a door and handle",
        "reason": "Closed storage structure that may contain fastening components or tools."
      },
      {
        "id": "table_drawers",
        "label": "Table Drawers",
        "visual_description": "Two blue drawers underneath the table with handles",
        "reason": "Closed storage structures that may contain fastening components or tools."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "table_drawers"
    ]
  }
  , "unsupported_reason": ""
  , "schema_version": 3
}
